using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using ResearchAgent.Tools;

var services = new ServiceCollection();

services.AddLogging(builder => builder.AddConsole().SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(
        modelId: Environment.GetEnvironmentVariable("AI_MODEL") ?? "gpt-4o-mini-2024-07-18",
        apiKey: Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set the OPENAI_API_KEY environment variable to your OpenAI API key.")));

await using var sp = services.BuildServiceProvider();

var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync,
        name: "web_search",
        description: "Search the web for information on a given query. Returns a list of relevant snippets."),
    AIFunctionFactory.Create(notepad.AddNote,
        name: "add_note",
        description: "Save a research note with a title and content for later reference."),
    AIFunctionFactory.Create(notepad.GetNotes,
        name: "get_notes",
        description: "Retrieve all saved research notes collected so far."),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the web_search tool
        2. Taking notes on key findings using the add_note tool
        3. After gathering enough information (at least 3 searches), retrieve your notes with get_notes
        4. Provide a comprehensive summary of your findings

        Be systematic: search for different aspects of the topic, take notes on important points,
        then synthesize everything into a clear summary.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes",
    tools: tools,
    loggerFactory: loggerFactory,
    serviceProvider: sp);

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    notepad.Clear();

    Console.WriteLine($"\nResearching: {input}\n");

    var session = await agent.CreateSessionAsync();
    var runOptions = new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    });

    var response = await agent.RunAsync($"Research the following topic and provide a summary: {input}", session, runOptions);

    Console.WriteLine("\n--- Research Summary ---");
    Console.WriteLine(response.Text);
    Console.WriteLine("--- End of Summary ---\n");

    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

