using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability using a search API.
/// Falls back to a simulated search if no API key is configured.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    [Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
    public static async Task<IReadOnlyList<SearchResult>> SearchAsync(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(query);

        // Use a real search API if configured, otherwise simulate results
        var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY");
        var searchEndpoint = Environment.GetEnvironmentVariable("SEARCH_ENDPOINT");

        if (!string.IsNullOrEmpty(searchApiKey) && !string.IsNullOrEmpty(searchEndpoint))
        {
            return await ExecuteRealSearchAsync(query, searchApiKey, searchEndpoint, cancellationToken);
        }

        return SimulateSearch(query);
    }

    private static async Task<IReadOnlyList<SearchResult>> ExecuteRealSearchAsync(
        string query, string apiKey, string endpoint, CancellationToken cancellationToken)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get,
            $"{endpoint}?q={Uri.EscapeDataString(query)}&count=5");
        request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

        var response = await HttpClient.SendAsync(request, cancellationToken);
        response.EnsureSuccessStatusCode();

        var searchResponse = await response.Content.ReadFromJsonAsync<BingSearchResponse>(cancellationToken);

        return searchResponse?.WebPages?.Value?.Select(p => new SearchResult
        {
            Title = p.Name ?? "",
            Snippet = p.Snippet ?? "",
            Url = p.Url ?? "",
        }).ToList() ?? [];
    }

    private static List<SearchResult> SimulateSearch(string query)
    {
        // Simulated search results for demonstration purposes
        Console.WriteLine($"  [WebSearch] Searching for: \"{query}\"");

        return
        [
            new SearchResult
            {
                Title = $"Overview of {query}",
                Snippet = $"A comprehensive overview of {query}. This topic encompasses various aspects including history, current developments, and future prospects. Experts in the field have noted significant progress in recent years.",
                Url = $"https://example.com/overview-{Uri.EscapeDataString(query.Replace(' ', '-'))}",
            },
            new SearchResult
            {
                Title = $"Recent developments in {query}",
                Snippet = $"Recent research has shown that {query} is evolving rapidly. Key developments include new methodologies, improved frameworks, and broader adoption across industries. Several peer-reviewed studies published in 2025 highlight these trends.",
                Url = $"https://example.com/developments-{Uri.EscapeDataString(query.Replace(' ', '-'))}",
            },
            new SearchResult
            {
                Title = $"Expert analysis: {query}",
                Snippet = $"Leading experts weigh in on {query}, discussing challenges and opportunities. The consensus points to continued growth, though concerns about scalability and accessibility remain. Industry leaders recommend a balanced approach.",
                Url = $"https://example.com/analysis-{Uri.EscapeDataString(query.Replace(' ', '-'))}",
            },
        ];
    }

    private sealed class BingSearchResponse
    {
        [JsonPropertyName("webPages")]
        public WebPages? WebPages { get; set; }
    }

    private sealed class WebPages
    {
        [JsonPropertyName("value")]
        public List<WebPage>? Value { get; set; }
    }

    private sealed class WebPage
    {
        [JsonPropertyName("name")]
        public string? Name { get; set; }

        [JsonPropertyName("snippet")]
        public string? Snippet { get; set; }

        [JsonPropertyName("url")]
        public string? Url { get; set; }
    }
}

public sealed class SearchResult
{
    public required string Title { get; set; }
    public required string Snippet { get; set; }
    public required string Url { get; set; }

    public override string ToString() => $"[{Title}] {Snippet} ({Url})";
}

using System.ComponentModel;

namespace ResearchAgent.Tools;

/// <summary>
/// A note-taking tool that allows the agent to store and retrieve research notes.
/// </summary>
public sealed class Notepad
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note with a title and content for later reference.")]
    public string AddNote(
        [Description("A short title for the note")] string title,
        [Description("The content of the note")] string content)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(title);
        ArgumentException.ThrowIfNullOrWhiteSpace(content);

        var note = new Note(title, content, DateTime.UtcNow);
        _notes.Add(note);

        Console.WriteLine($"  [Notepad] Saved note: \"{title}\"");
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public IReadOnlyList<Note> GetNotes()
    {
        Console.WriteLine($"  [Notepad] Retrieving {_notes.Count} note(s)");
        return _notes.AsReadOnly();
    }

    public void Clear() => _notes.Clear();
}

public sealed record Note(string Title, string Content, DateTime Timestamp);

